mapper.update:
update idevelop_safeaccess_user_access
set is_deleted = 1
where id = #{userAccessId}

mapper.select:
select *from (SELECT t.id id, t.subnet_name subnetName, t.broadcast_address broadcastAddress, t.subnet_address subnetAddress, t.subnet_gateway subnetGateway, t.subnet_mask subnetMask, t.address_resolution_ip addressResolutionIp, t.dnsip dnsip, t.dnsip2 dnsip2, t.code code, w.sw_ip switchboardip, w.sw_name switchName, t.switchboard switchboard, t.user_group userGroup, t.vlan_id vlanId, t.vlan_name vlanName, i.name institutionName, t.institution_code institutionCode, t.fill_date fillDate, t.fill_man fillMan, t.segment segment, t.ip1 ip1, t.location1 location1, t.ip2 ip2, t.location2 location2, t.default_time defaultTime, t.default_lease_time defaultLeaseTime, t.sp_id spId, t.sp_name spName, t.create_time crateDate, t.update_time updateDate, t.is_public isPublic, t.bak_col2 bak2, t.bak_col3 bak3 FROM idevelop_safeaccess_subnet t left join idevelop_safeaccess_switche w on t.switchboard=w.id and w.is_deleted = 0 left join idevelop_region i on i.code=t.institution_code
t.is_deleted = 0
and t.subnet_name like CONCAT('%',#{subnetName,jdbcType=VARCHAR},'%')
and t.code like CONCAT('%',#{code,jdbcType=VARCHAR},'%')
and t.vlan_id like CONCAT('%',#{vlanId,jdbcType=VARCHAR},'%')
and t.subnet_address like CONCAT('%',#{subnetAddress},'%')
and t.sp_name like CONCAT('%',#{spName,jdbcType=VARCHAR},'%')
and t.institution_code like CONCAT('%',#{institutionCode,jdbcType=VARCHAR},'%')
and t.id=#{id,jdbcType=VARCHAR}
and t.subnet_mask=#{subnetMask,jdbcType=VARCHAR}
and t.institution_code=#{deptCode,jdbcType=VARCHAR}
and t.is_public=#{isPublic,jdbcType=VARCHAR}
and t.region_code like CONCAT(#{regionCode,jdbcType=VARCHAR},'%')
union SELECT t.id id, t.subnet_name subnetName, t.broadcast_address broadcastAddress, t.subnet_address subnetAddress, t.subnet_gateway subnetGateway, t.subnet_mask subnetMask, t.address_resolution_ip addressResolutionIp, t.dnsip dnsip, t.dnsip2 dnsip2, t.code code, w.sw_ip switchboardip, w.sw_name switchName, t.switchboard switchboard, t.user_group userGroup, t.vlan_id vlanId, t.vlan_name vlanName, i.name institutionName, t.institution_code institutionCode, t.fill_date fillDate, t.fill_man fillMan, t.segment segment, t.ip1 ip1, t.location1 location1, t.ip2 ip2, t.location2 location2, t.default_time defaultTime, t.default_lease_time defaultLeaseTime, t.sp_id spId, t.sp_name spName, t.create_time crateDate, t.update_time updateDate, t.is_public isPublic, t.bak_col2 bak2, t.bak_col3 bak3 FROM idevelop_safeaccess_subnet t left join idevelop_safeaccess_switche w on t.switchboard = w.id and w.is_deleted = 0 left join idevelop_region i on i.code=t.institution_code where t.is_deleted = 0
and t.subnet_name like CONCAT('%',#{subnetName,jdbcType=VARCHAR},'%')
and t.code like CONCAT('%',#{code,jdbcType=VARCHAR},'%')
and t.vlan_id like CONCAT('%',#{vlanId,jdbcType=VARCHAR},'%')
and t.subnet_address like CONCAT('%',#{subnetAddress},'%')
and t.sp_name like CONCAT('%',#{spName,jdbcType=VARCHAR},'%')
and t.institution_code like CONCAT('%',#{reinstitutionCode,jdbcType=VARCHAR},'%')
and t.id=#{id,jdbcType=VARCHAR}
and t.subnet_mask=#{subnetMask,jdbcType=VARCHAR}
and t.institution_code=#{deptCode,jdbcType=VARCHAR}
and t.region_code like CONCAT(#{regionCode,jdbcType=VARCHAR},'%')
and t.is_public = '1'
)temp order by temp.fillDate desc, convert(substring_index(temp.subnetAddress,'.',1),signed ), convert(substring_index(substring_index(temp.subnetAddress,'.',2),'.',-1),signed ), convert(substring_index(substring_index(temp.subnetAddress,'.',3),'.',-1),signed ), convert(substring_index(temp.subnetAddress,'.',-1),signed ) desc

select ippool_segment from idevelop_safeaccess_subnet_ippool

    and subnet_id = #{subnetId}
    and ippool_id = #{ippoolId}
    and ippool_segment = #{ippoolSegment}

order by convert(substring_index(ippool_segment,'.',1),signed ),
convert(substring_index(substring_index(ippool_segment,'.',2),'.',-1),signed ),
convert(substring_index(substring_index(ippool_segment,'.',3),'.',-1),signed ),
convert(substring_index(ippool_segment,'.',-1),signed ) desc
